'use strict';
// Bakes the Lucide icons used by the UI (ISC licence, https://lucide.dev) into public/icons.js.
// Needs: npm i -D lucide-static. The generated file is committed, so the till never needs the internet or the package.
const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, 'node_modules', 'lucide-static');
const names = ['layout-dashboard', 'package', 'truck', 'receipt', 'users', 'printer', 'store', 'globe', 'shopping-cart', 'package-check', 'package-plus', 'plus', 'log-out',
  'refresh-cw', 'search', 'search-x', 'smartphone', 'life-buoy', 'key-round', 'pencil', 'trash-2', 'x', 'check', 'circle-check', 'circle-x', 'upload', 'download', 'triangle-alert',
  'bell', 'scan-barcode', 'delete', 'external-link', 'arrow-right', 'arrow-down', 'trending-up', 'settings', 'baby', 'sun', 'pill', 'droplets', 'sparkles', 'stethoscope', 'leaf',
  'message-circle', 'map-pin', 'shopping-bag', 'lock-keyhole', 'user-plus', 'shield-user', 'circle', 'file-check', 'monitor', 'activity', 'hash', 'heart-handshake', 'chevron-down', 'wifi'];
const body = {};
for (const n of names) {
  const svg = fs.readFileSync(path.join(dir, 'icons', n + '.svg'), 'utf8');
  const inner = /<svg[^>]*>([\s\S]*?)<\/svg>/.exec(svg)[1].replace(/\s+/g, ' ').trim();
  body[n] = inner;
}
const version = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8')).version;
const css = [
  '.ic{display:inline-block;vertical-align:-.2em;flex:none}',
  '.nav-icon{width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:0}',
  '.button .ic,.product-add .ic,.owner-link-button .ic,.owner-bottom-link .ic{vertical-align:-.28em}',
  '.button .ic:first-child{margin-right:7px}',
  '.product-add{display:flex;align-items:center;justify-content:center;gap:7px}',
  '.owner-link-button .ic:last-child,.owner-bottom-link .ic:last-child{margin-left:6px}',
  '.brand-icon .brand-img{width:auto;height:26px;display:block}',
  '.brand-compact .brand-icon{width:40px;height:40px}',
  '.auth-logo{display:block;width:250px;max-width:70%;height:auto}',
  '.status-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#2f9e6b;margin-right:7px;vertical-align:1px}',
  '.modal-x{display:inline-grid;place-items:center;width:36px;height:36px;border-radius:9px;cursor:pointer;color:#6c7a72;padding:0}',
  '.modal-x:hover{background:#eef2ee}',
  '.metric-mark .ic,.owner-alert-icon .ic,.owner-no-alert span .ic,.success-mark .ic,.shop-preview-icon .ic,.owner-quick-action span .ic{display:block}',
  '.scan-login-frame>span,.scan-symbol{display:inline-grid;place-items:center}',
  '.receipt-logo{display:block;margin:0 auto 3px;width:26mm;height:auto}',
  '.shop-mark img,.brand-mark img{display:block;height:22px;width:auto;margin:auto}',
  '.brand-compact .brand-name,.brand-compact .brand-sub{display:block;line-height:1.2;white-space:nowrap}',
  '[data-ico]{display:inline-flex;align-items:center;justify-content:center}'
].join('');
const out = '/* Icons: Lucide ' + version + ' (ISC licence, see icons-LICENSE.txt). Generated by build/make-icons.js - do not edit by hand. */\n(function(){\n' +
  'var P=' + JSON.stringify(body) + ';\n' +
  'window.ICONS=P;\n' +
  'window.ico=function(name,size,cls){var s=size||18;return \'<svg class="ic\'+(cls?\' \'+cls:\'\')+\'" width="\'+s+\'" height="\'+s+\'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">\'+(P[name]||P.circle)+\'</svg>\';};\n' +
  'var style=document.createElement("style");style.textContent=' + JSON.stringify(css) + ';document.head.appendChild(style);\n' +
  'function fill(root){var list=(root||document).querySelectorAll("[data-ico]:not([data-ico-done])");for(var i=0;i<list.length;i++){var el=list[i];el.innerHTML=window.ico(el.getAttribute("data-ico"),Number(el.getAttribute("data-size"))||18);el.setAttribute("data-ico-done","1");}}\n' +
  'window.fillIcons=fill;\n' +
  'function start(){fill();try{new MutationObserver(function(){fill();}).observe(document.body,{childList:true,subtree:true});}catch(e){}}\n' +
  'if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",start);else start();\n' +
  '})();\n';
fs.writeFileSync(path.resolve(__dirname, '..', 'public', 'icons.js'), out);
fs.copyFileSync(path.join(dir, 'LICENSE'), path.resolve(__dirname, '..', 'public', 'icons-LICENSE.txt'));
console.log('icons.js written: ' + names.length + ' icons, Lucide ' + version + ', ' + Math.round(out.length / 1024) + ' KB');
